package live.linghe.privateinput;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.io.*;import java.util.concurrent.*;import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.json.*;
/** Actual product serializer in Android VM; no Context, permissions, storage manager or network. */
public final class CliDecisionContractCheck {
 static final class IsolatedContext extends ContextWrapper {
  final File directory;IsolatedContext(File directory){super(null);this.directory=directory;directory.mkdirs();}
  @Override public Context getApplicationContext(){return this;}
  @Override public File getDatabasePath(String name){return new File(directory,name);}
  @Override public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory){return SQLiteDatabase.openOrCreateDatabase(getDatabasePath(name),factory);}
  @Override public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory,DatabaseErrorHandler handler){return SQLiteDatabase.openOrCreateDatabase(getDatabasePath(name).getAbsolutePath(),factory,handler);}
 }
 static int n;static void require(boolean b,String label){n++;if(!b)throw new AssertionError(label);}
 public static void main(String[] args)throws Exception{
  String[][] rows=new String[34][];rows[0]=new String[]{"","","444","",""};for(int i=1;i<rows.length;i++)rows[i]=new String[]{""+i,"合成候选"+i,"he cheng"};InputDecisionEvidence value=new InputDecisionEvidence.Owner().snapshot("444",rows,1000000).model("39",true).marked("h h h","host_acknowledged");
  InputDecisionEvidence.Candidate selected=InputDecisionEvidence.candidate(value.snapshot,rows[33],32);InputDecisionEvidence press=value.event("press",selected,"touch",null,null,1100000),release=value.event("release",selected,"touch",null,null,1200000),choice=value.event("selection",selected,"touch",null,null,1300000).touch(press,release);
  JSONObject snapshot=ActivityArchiveManager.decisionJSON(value),selection=ActivityArchiveManager.decisionJSON(choice),commit=ActivityArchiveManager.decisionJSON(choice.event("commit",selected,"touch",null,UUID.randomUUID().toString(),1400000));
  require(snapshot.getJSONArray("candidates").length()==5&&snapshot.getInt("observed_count")==5,"bounded preview");require(snapshot.getString("coverage").equals("published_subset"),"not falsely claiming exposure");require(!snapshot.has("total_count")&&snapshot.getBoolean("truncated"),"unknown full count not invented");require(!selection.has("candidates"),"selection does not redump candidates");require(selection.getInt("selected_rank")==32&&selection.getJSONObject("selected_candidate").getInt("absolute_rank")==32,"outside preview selected item full");require(selection.getString("press_state_id").equals(value.state)&&selection.getString("release_state_id").equals(value.state),"bound touch snapshots");require(selection.getLong("press_monotonic_us")==1100000&&selection.getLong("release_monotonic_us")==1200000,"actual touch monotonic times");require(commit.getString("marked_text").equals("h h h")&&commit.getString("marked_status").equals("host_acknowledged"),"marked text distinct from output");require(commit.has("output_event_id"),"output ID join");require(commit.getString("clock_domain").equals(snapshot.getString("clock_domain")),"one monotonic domain");require(commit.getString("core_hash").matches("[a-f0-9]{64}")&&commit.getString("resource_hash").matches("[a-f0-9]{64}")&&commit.getString("policy_hash").matches("[a-f0-9]{64}"),"actual build hashes");require(!ActivityArchiveManager.decisionJSON(value.model(null,null)).has("local_overlay"),"unknown overlay omitted");require(!ActivityArchiveManager.decisionJSON(choice.event("commit",selected,"touch",null,null,1400000)).has("output_event_id"),"diagnostic only commit no invented output ID");require(commit.getString("model_version").equals("39")&&!commit.has("model_hash"),"known model version, unknown hash omitted");
  String longText=String.join("",Collections.nCopies(200,"长"));InputDecisionEvidence.Candidate longChoice=InputDecisionEvidence.candidate(value.snapshot,new String[]{"long",longText,"chang"},0);JSONObject longSelected=ActivityArchiveManager.decisionJSON(value.event("selection",longChoice,"touch",null,null,1500000));require(!longSelected.has("selected_candidate")&&longSelected.getString("reason").equals("selected_text_too_large")&&longSelected.has("selected_candidate_id"),"oversize selection not falsely complete");
  InputDecisionEvidence.Scope scope=new InputDecisionEvidence.Scope();long token=scope.current();InputDecisionEvidence.Scope.Frozen frozen=scope.freeze(token,true,true,"synthetic-old-session","synthetic-old-epoch");
  File directory=new File(new File(args[0]).getParentFile(),"queue");ActivityArchiveQueue queue=new ActivityArchiveQueue(new IsolatedContext(directory));ExecutorService writer=Executors.newSingleThreadExecutor();CountDownLatch ready=new CountDownLatch(1);
  try{JSONObject terminal=ActivityArchiveManager.decisionJSON(value.event("cancel",null,null,"focus_lost",null,1600000));JSONObject envelope=new JSONObject().put("event_id",UUID.randomUUID().toString()).put("provider_id","ime.diagnostic.v1").put("event_type","source_import").put("input_session",frozen.session).put("editor_epoch",frozen.epoch).put("content",new JSONObject().put("text","444")).put("extensions",new JSONObject().put(InputDecisionEvidence.KEY,terminal));Future<Boolean> saved=writer.submit(()->{ready.await();return queue.enqueue(envelope,7);});scope.advance();ready.countDown();require(saved.get(5,TimeUnit.SECONDS),"terminal persists after editor pause");JSONObject stored=queue.batch(7).getJSONObject(0);require(stored.getString("input_session").equals("synthetic-old-session")&&stored.getString("editor_epoch").equals("synthetic-old-epoch"),"old metadata never relabeled new editor");require(scope.freeze(token,true,true,"new","new")==null,"late old nonterminal rejected");require(scope.freeze(scope.current(),true,false,"new","new")==null&&queue.pending()==1,"default off zero new events");}finally{ready.countDown();writer.shutdownNow();queue.close();}
  JSONArray cases=new JSONArray().put(snapshot).put(selection).put(commit).put(longSelected);Files.write(Paths.get(args[0]),cases.toString(2).getBytes(StandardCharsets.UTF_8));System.out.println("PASS assertions="+n+" serializer=actualProduct AndroidVM=true realAppData=false permissionsChanged=false network=false");
 }
}
